using System;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
public static class B4DoorProbe {public static object Run(){var root=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("B4_"));return root.GetComponentsInChildren<Transform>().Where(t=>t.name.Contains("닫힌문")||t.name.Contains("아치문틀")).Select(t=>new{name=t.name,pos=t.position.ToString(),rotation=t.eulerAngles.ToString(),scale=t.localScale.ToString(),renderers=t.GetComponentsInChildren<Renderer>().Select(r=>new{name=r.name,center=r.bounds.center.ToString(),size=r.bounds.size.ToString(),active=r.enabled,mats=r.sharedMaterials.Select(m=>m.name).ToArray()}).ToArray()}).ToArray();}}
